begin read only;
set local statement_timeout='8s';
set local lock_timeout='1s';
with t as(select n.nspname schema,c.relname name,c.relkind kind,c.relrowsecurity rls,c.relforcerowsecurity force_rls,pg_get_userbyid(c.relowner) owner,c.relacl::text acl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind in('r','p','v','m','S') order by 1,2),
a as(select n.nspname schema,c.relname relation,a.attname name,format_type(a.atttypid,a.atttypmod) type,a.attnotnull not_null,pg_get_expr(d.adbin,d.adrelid) default_expression,a.attacl::text acl from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in('public','private') and c.relkind in('r','p','v','m') and a.attnum>0 and not a.attisdropped order by 1,2,a.attnum),
f as(select n.nspname schema,p.proname name,pg_get_function_identity_arguments(p.oid) args,pg_get_userbyid(p.proowner) owner,p.prosecdef security_definer,p.proconfig config,p.proacl::text acl,md5(pg_get_functiondef(p.oid)) definition_md5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('public','private') order by 1,2,3),
c as(select n.nspname schema,cl.relname relation,k.conname name,pg_get_constraintdef(k.oid) definition from pg_constraint k join pg_class cl on cl.oid=k.conrelid join pg_namespace n on n.oid=cl.relnamespace where n.nspname in('public','private') order by 1,2,3),
p as(select schemaname schema,tablename relation,policyname name,permissive,roles::text,cmd,qual,with_check from pg_policies where schemaname in('public','private','storage') order by 1,2,3),
i as(select schemaname schema,tablename relation,indexname name,indexdef definition from pg_indexes where schemaname in('public','private') order by 1,2,3),
g as(select n.nspname schema,c.relname relation,t.tgname name,pg_get_triggerdef(t.oid) definition from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and not t.tgisinternal order by 1,2,3),
r as(select rolname name,rolsuper superuser,rolinherit inherit,rolcreaterole create_role,rolcreatedb create_db,rolcanlogin login,rolreplication replication,rolbypassrls bypass_rls from pg_roles order by rolname),
m as(select pg_get_userbyid(roleid) role,pg_get_userbyid(member) member,pg_get_userbyid(grantor) grantor,admin_option from pg_auth_members order by 1,2,3),
s as(select nspname schema,pg_get_userbyid(nspowner) owner,nspacl::text acl,has_schema_privilege('anon',oid,'CREATE') anon_create,has_schema_privilege('authenticated',oid,'CREATE') authenticated_create from pg_namespace where nspname in('public','private','storage') order by 1),
h as(select version,name from supabase_migrations.schema_migrations order by version)
select jsonb_build_object('observedAt',clock_timestamp(),'database',current_database(),'user',current_user,'readOnly',current_setting('transaction_read_only'),'tables',(select jsonb_agg(to_jsonb(t)) from t),'columns',(select jsonb_agg(to_jsonb(a)) from a),'functions',(select jsonb_agg(to_jsonb(f)) from f),'constraintsCount',(select count(*) from c),'constraintsMd5',(select md5(coalesce(jsonb_agg(to_jsonb(c))::text,'')) from c),'policies',(select jsonb_agg(to_jsonb(p)) from p),'indexesCount',(select count(*) from i),'indexesMd5',(select md5(coalesce(jsonb_agg(to_jsonb(i))::text,'')) from i),'triggersCount',(select count(*) from g),'triggersMd5',(select md5(coalesce(jsonb_agg(to_jsonb(g))::text,'')) from g),'roles',(select jsonb_agg(to_jsonb(r)) from r),'memberships',(select jsonb_agg(to_jsonb(m)) from m),'schemas',(select jsonb_agg(to_jsonb(s)) from s),'migrations',(select jsonb_agg(to_jsonb(h)) from h)) as catalog;
rollback;
